import React, { useState, useEffect } from 'react';
import Modal from '../../components/ui/Modal';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import {
  Wrench, Plus, Search, Clock, CheckCircle,
  AlertTriangle, MessageSquare, ChevronRight,
} from 'lucide-react';

const statuses = ['Pending', 'In Progress', 'Resolved'];
const priorities = ['Low', 'Medium', 'High', 'Urgent'];

const MaintenancePage = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterPriority, setFilterPriority] = useState('all');
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState({ title: '', description: '', priority: 'Medium', propertyName: '' });

  useEffect(() => { loadRequests(); }, []);

  const loadRequests = () => {
    setRequests([
      { id: '1', title: 'Leaking faucet - Kitchen', description: 'The kitchen sink faucet is leaking water continuously', propertyName: 'Sunset Apartments', unitNumber: '3B', priority: 'High', status: 'In Progress', assignedTo: 'John (Plumber)', createdAt: '2026-05-18' },
      { id: '2', title: 'Broken light fixture', description: 'Hallway light on 2nd floor not working', propertyName: 'Oak Villa', unitNumber: 'Common', priority: 'Low', status: 'Pending', assignedTo: null, createdAt: '2026-05-16' },
      { id: '3', title: 'AC not cooling', description: 'Air conditioning unit in bedroom not working properly', propertyName: 'Downtown Complex', unitNumber: '12', priority: 'Urgent', status: 'Pending', assignedTo: null, createdAt: '2026-05-15' },
      { id: '4', title: 'Water heater repair', description: 'No hot water in bathroom', propertyName: 'Pine Court', unitNumber: '2B', priority: 'High', status: 'In Progress', assignedTo: 'Mary (Technician)', createdAt: '2026-05-14' },
      { id: '5', title: 'Paint touch-up', description: 'Scratches on hallway wall need painting', propertyName: 'Hillview Cottages', unitNumber: '5', priority: 'Low', status: 'Resolved', assignedTo: 'John (Plumber)', createdAt: '2026-05-10' },
    ]);
    setLoading(false);
  };

  const filtered = requests.filter(r => {
    const q = search.toLowerCase();
    const matchSearch = r.title?.toLowerCase().includes(q) || r.propertyName?.toLowerCase().includes(q);
    const matchStatus = filterStatus === 'all' || r.status === filterStatus;
    const matchPriority = filterPriority === 'all' || r.priority === filterPriority;
    return matchSearch && matchStatus && matchPriority;
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.title || !form.description) { toast.error('Title and description required'); return; }
    setRequests(prev => [...prev, {
      id: Date.now().toString(), ...form, status: 'Pending', assignedTo: null,
      createdAt: new Date().toISOString().split('T')[0],
    }]);
    toast.success('Request submitted');
    setShowModal(false);
    setForm({ title: '', description: '', priority: 'Medium', propertyName: '' });
  };

  const updateStatus = (id, newStatus) => {
    setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus } : r));
    toast.success(`Status updated to "${newStatus}"`);
  };

  const assignTask = (id) => {
    const name = prompt('Enter staff/technician name:');
    if (!name) return;
    setRequests(prev => prev.map(r => r.id === id ? { ...r, assignedTo: name } : r));
    toast.success(`Assigned to ${name}`);
  };

  const canManage = ['admin', 'staff', 'landlord', 'manager'].includes(user?.role);

  const pendingCount = requests.filter(r => r.status === 'Pending').length;
  const inProgressCount = requests.filter(r => r.status === 'In Progress').length;
  const resolvedCount = requests.filter(r => r.status === 'Resolved').length;

  const priorityBadge = (p) => {
    const colors = { Low: 'badge-gray', Medium: 'badge-yellow', High: 'badge-red', Urgent: 'bg-red-50 text-red-700' };
    return <span className={colors[p] || 'badge-gray'}>{p}</span>;
  };

  const statusIcon = (status) => {
    const map = {
      'Pending': { icon: Clock, color: 'text-amber-500', bg: 'bg-amber-50' },
      'In Progress': { icon: AlertTriangle, color: 'text-blue-500', bg: 'bg-blue-50' },
      'Resolved': { icon: CheckCircle, color: 'text-emerald-500', bg: 'bg-emerald-50' },
    };
    const s = map[status] || map['Pending'];
    return <div className={`p-2 rounded-lg ${s.bg}`}><s.icon className={`w-4 h-4 ${s.color}`} /></div>;
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h2 className="page-heading">Maintenance</h2>
          <p className="page-subtitle">{pendingCount} pending · {inProgressCount} in progress · {resolvedCount} resolved</p>
        </div>
        <button onClick={() => setShowModal(true)} className="btn-primary flex items-center gap-2">
          <Plus className="w-4 h-4" /> New Request
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="stat-card"><p className="stat-label">Pending</p><p className="stat-value text-amber-600">{pendingCount}</p></div>
        <div className="stat-card"><p className="stat-label">In Progress</p><p className="stat-value text-blue-600">{inProgressCount}</p></div>
        <div className="stat-card"><p className="stat-label">Resolved</p><p className="stat-value text-emerald-600">{resolvedCount}</p></div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search requests..." value={search}
            onChange={(e) => setSearch(e.target.value)} className="input-primary pl-9" />
        </div>
        <select value={filterPriority} onChange={(e) => setFilterPriority(e.target.value)} className="input-primary sm:w-36">
          <option value="all">All Priority</option>
          {priorities.map(p => <option key={p} value={p}>{p}</option>)}
        </select>
        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="input-primary sm:w-36">
          <option value="all">All Status</option>
          {statuses.map(s => <option key={s} value={s}>{s}</option>)}
        </select>
      </div>

      {loading ? (
        <div className="text-center py-16"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto" /></div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <Wrench className="w-12 h-12 mx-auto mb-3 text-gray-300" />
          <p className="text-sm font-medium text-gray-500">No maintenance requests</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map(r => (
            <div key={r.id} className="card p-4 hover:shadow-md transition-shadow">
              <div className="flex items-start gap-4">
                {statusIcon(r.status)}
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <h3 className="font-medium text-gray-900 text-sm">{r.title}</h3>
                      <p className="text-xs text-gray-500 mt-0.5">{r.propertyName} {r.unitNumber && `· Unit ${r.unitNumber}`}</p>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      {priorityBadge(r.priority)}
                      <span className={`badge ${
                        r.status === 'Resolved' ? 'badge-green' :
                        r.status === 'In Progress' ? 'badge-blue' : 'badge-yellow'
                      }`}>{r.status}</span>
                    </div>
                  </div>
                  {r.description && <p className="text-sm text-gray-600 mt-2">{r.description}</p>}
                  <div className="flex items-center gap-4 mt-3 text-xs text-gray-400">
                    <span className="flex items-center gap-1"><MessageSquare className="w-3 h-3" /> {r.assignedTo || 'Unassigned'}</span>
                    <span>{r.createdAt}</span>
                  </div>
                  <div className="flex flex-wrap gap-2 mt-3 pt-3 border-t border-gray-100">
                    {canManage && r.status === 'Pending' && (
                      <>
                        <button onClick={() => updateStatus(r.id, 'In Progress')}
                          className="text-xs px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 font-medium">
                          Start Progress
                        </button>
                        {!r.assignedTo && (
                          <button onClick={() => assignTask(r.id)}
                            className="text-xs px-3 py-1.5 bg-gray-50 text-gray-700 rounded-lg hover:bg-gray-100 font-medium">
                            Assign Staff
                          </button>
                        )}
                      </>
                    )}
                    {canManage && r.status === 'In Progress' && (
                      <button onClick={() => updateStatus(r.id, 'Resolved')}
                        className="text-xs px-3 py-1.5 bg-emerald-50 text-emerald-700 rounded-lg hover:bg-emerald-100 font-medium">
                        <CheckCircle className="w-3 h-3 inline mr-1" /> Mark Resolved
                      </button>
                    )}
                    {!canManage && r.status === 'Pending' && (
                      <span className="text-xs text-gray-400 flex items-center gap-1"><Clock className="w-3 h-3" /> Awaiting assignment</span>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title="New Maintenance Request">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Title *</label>
            <input type="text" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })}
              className="input-field" required placeholder="e.g. Leaking faucet in kitchen" />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Description *</label>
            <textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
              className="input-field" rows="3" required placeholder="Describe the issue in detail..." />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Priority</label>
              <select value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className="input-field">
                {priorities.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Property</label>
              <input type="text" value={form.propertyName} onChange={(e) => setForm({ ...form, propertyName: e.target.value })}
                className="input-field" placeholder="Property name" />
            </div>
          </div>
          <div className="flex gap-3 pt-2">
            <button type="submit" className="btn-primary flex-1">Submit Request</button>
            <button type="button" onClick={() => setShowModal(false)} className="btn-secondary flex-1">Cancel</button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default MaintenancePage;
