import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import {
  MessageCircle, Send, Search, Phone, MoreVertical,
  Check, CheckCheck, User,
} from 'lucide-react';

const initialConversations = [
  {
    id: '1', name: 'Alice Njeri', role: 'tenant', property: 'Sunset Apt 3B',
    avatar: 'A', online: true, unread: 2,
    messages: [
      { id: 1, from: 'them', text: 'Hi, the faucet in the kitchen is leaking', time: '10:30 AM' },
      { id: 2, from: 'me', text: 'Thanks for letting me know. I will send a plumber tomorrow morning.', time: '10:35 AM' },
      { id: 3, from: 'them', text: 'Okay, thank you! What time should I expect them?', time: '10:36 AM' },
      { id: 4, from: 'me', text: 'Around 9 AM. I will confirm once scheduled.', time: '10:40 AM' },
      { id: 5, from: 'them', text: 'Perfect, thank you!', time: '10:42 AM' },
    ],
  },
  {
    id: '2', name: 'Brian Koech', role: 'tenant', property: 'Oak Villa 7A',
    avatar: 'B', online: false, unread: 0,
    messages: [
      { id: 1, from: 'them', text: 'I have paid the rent for May', time: 'Yesterday' },
      { id: 2, from: 'me', text: 'Received, thank you Brian!', time: 'Yesterday' },
    ],
  },
  {
    id: '3', name: 'Carol Wanjiku', role: 'tenant', property: 'Downtown 12',
    avatar: 'C', online: true, unread: 1,
    messages: [
      { id: 1, from: 'them', text: 'Is the parking space available?', time: '2:15 PM' },
    ],
  },
  {
    id: '4', name: 'Daniel Mwangi', role: 'tenant', property: 'Pine Court 2B',
    avatar: 'D', online: false, unread: 0,
    messages: [
      { id: 1, from: 'me', text: 'Your lease renewal is coming up next month.', time: 'May 15' },
      { id: 2, from: 'them', text: 'Yes, I would like to renew for another year.', time: 'May 15' },
    ],
  },
];

const ChatPage = () => {
  const { user } = useAuth();
  const [conversations, setConversations] = useState(initialConversations);
  const [activeChat, setActiveChat] = useState(null);
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [showSidebar, setShowSidebar] = useState(true);
  const messagesEndRef = useRef(null);
  const isStaff = ['admin', 'staff', 'landlord', 'manager'].includes(user?.role);

  useEffect(() => {
    if (conversations.length > 0 && !activeChat) {
      setActiveChat(conversations[0]);
    }
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [activeChat?.messages]);

  const filtered = conversations.filter(c =>
    c.name.toLowerCase().includes(search.toLowerCase())
  );

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message.trim() || !activeChat) return;
    const newMsg = { id: Date.now(), from: 'me', text: message, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };
    setConversations(prev => prev.map(c =>
      c.id === activeChat.id ? { ...c, messages: [...c.messages, newMsg], unread: 0 } : c
    ));
    setMessage('');

    setTimeout(() => {
      const replies = [
        'Okay, noted!',
        'Thank you for the update.',
        'I will check on that.',
        'Sure, no problem.',
        'Let me confirm and get back to you.',
      ];
      const reply = { id: Date.now() + 1, from: 'them', text: replies[Math.floor(Math.random() * replies.length)], time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };
      setConversations(prev => prev.map(c =>
        c.id === activeChat.id ? { ...c, messages: [...c.messages, reply] } : c
      ));
    }, 1500);
  };

  const activeConv = conversations.find(c => c.id === activeChat?.id);

  return (
    <div className="h-[calc(100vh-7rem)] lg:h-[calc(100vh-5.5rem)] -mx-4 lg:-mx-6 -mb-4 lg:-mb-6 flex">
      <div className={`${showSidebar ? 'flex' : 'hidden'} lg:flex flex-col w-full lg:w-80 bg-white border-r border-gray-200 shrink-0`}>
        <div className="p-4 border-b border-gray-200">
          <h2 className="text-base font-semibold text-gray-900 mb-3">Messages</h2>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input type="text" placeholder="Search conversations..." value={search}
              onChange={(e) => setSearch(e.target.value)} className="input-field pl-9" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {filtered.length === 0 ? (
            <div className="text-center py-8 text-gray-400 text-sm">No conversations</div>
          ) : filtered.map(c => (
            <button key={c.id} onClick={() => { setActiveChat(c); setShowSidebar(false); }}
              className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 transition-colors text-left border-b border-gray-50 ${
                activeChat?.id === c.id ? 'bg-blue-50' : ''
              }`}>
              <div className="relative shrink-0">
                <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                  <span className="text-sm font-semibold text-blue-600">{c.avatar}</span>
                </div>
                {c.online && <span className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-emerald-500 border-2 border-white rounded-full" />}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium text-gray-900 truncate">{c.name}</p>
                  <span className="text-[10px] text-gray-400">{c.messages[c.messages.length - 1]?.time}</span>
                </div>
                <p className="text-xs text-gray-500 truncate mt-0.5">{c.property} · {c.role}</p>
                <p className="text-xs text-gray-400 truncate mt-0.5">{c.messages[c.messages.length - 1]?.text}</p>
              </div>
              {c.unread > 0 && (
                <span className="shrink-0 w-5 h-5 bg-blue-600 text-white text-[10px] font-bold rounded-full flex items-center justify-center">{c.unread}</span>
              )}
            </button>
          ))}
        </div>
      </div>

      <div className={`${!showSidebar ? 'flex' : 'hidden'} lg:flex flex-1 flex-col bg-gray-50`}>
        {activeConv ? (
          <>
            <div className="flex items-center gap-3 px-4 py-3 bg-white border-b border-gray-200 sticky top-0 z-10">
              <button onClick={() => setShowSidebar(true)} className="lg:hidden p-1 text-gray-500 hover:text-gray-700">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
              </button>
              <div className="w-9 h-9 bg-blue-100 rounded-full flex items-center justify-center shrink-0">
                <span className="text-sm font-semibold text-blue-600">{activeConv.avatar}</span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-gray-900">{activeConv.name}</p>
                <p className="text-xs text-gray-500">{activeConv.property} {activeConv.online ? '· Online' : ''}</p>
              </div>
              <button className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-gray-100">
                <Phone className="w-4 h-4" />
              </button>
              <button className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-gray-100">
                <MoreVertical className="w-4 h-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-3">
              {activeConv.messages.map(msg => (
                <div key={msg.id} className={`flex ${msg.from === 'me' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[75%] lg:max-w-[60%] ${
                    msg.from === 'me'
                      ? 'bg-blue-600 text-white rounded-2xl rounded-br-md'
                      : 'bg-white border border-gray-200 rounded-2xl rounded-bl-md'
                  } px-4 py-2.5`}>
                    <p className={`text-sm ${msg.from === 'me' ? 'text-white' : 'text-gray-800'}`}>{msg.text}</p>
                    <p className={`text-[10px] mt-1 flex items-center gap-1 ${
                      msg.from === 'me' ? 'text-blue-200' : 'text-gray-400'
                    }`}>
                      {msg.time}
                      {msg.from === 'me' && <CheckCheck className="w-3 h-3" />}
                    </p>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={sendMessage} className="p-3 bg-white border-t border-gray-200">
              <div className="flex items-center gap-2">
                <input type="text" placeholder="Type a message..." value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  className="input-field flex-1" />
                <button type="submit" disabled={!message.trim()}
                  className="p-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                  <Send className="w-4 h-4" />
                </button>
              </div>
            </form>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center text-gray-400">
            <div className="text-center">
              <MessageCircle className="w-16 h-16 mx-auto mb-4 text-gray-300" />
              <p className="text-sm font-medium text-gray-500">Select a conversation</p>
              <p className="text-xs mt-1">Choose a tenant or staff to message</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;
