import React, { createContext, useContext, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import toast from 'react-hot-toast';

const DEMO_USERS_KEY = 'rentalsync_demo_users';
const DEMO_TOKEN_PREFIX = 'demo_token_';

function getDemoUsers() {
  try { return JSON.parse(localStorage.getItem(DEMO_USERS_KEY)) || {}; } catch { return {}; }
}
function saveDemoUsers(users) {
  localStorage.setItem(DEMO_USERS_KEY, JSON.stringify(users));
}

const DEFAULT_DEMO_USERS = {
  'admin@rentalsync.com': { id: 'demo_admin_1', name: 'Admin User', email: 'admin@rentalsync.com', password: 'Admin@123', phone: '+1 234 567 890', role: 'admin' },
  'tenant@rentalsync.com': { id: 'demo_tenant_1', name: 'Tenant User', email: 'tenant@rentalsync.com', password: 'Tenant@123', phone: '+1 234 567 891', role: 'tenant' },
  'staff@rentalsync.com': { id: 'demo_staff_1', name: 'Staff User', email: 'staff@rentalsync.com', password: 'Staff@123', phone: '+1 234 567 892', role: 'staff' },
};

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);

  // Seed demo users once
  useEffect(() => {
    const users = getDemoUsers();
    if (Object.keys(users).length === 0) saveDemoUsers(DEFAULT_DEMO_USERS);
  }, []);

  // Initialize session synchronously (no API calls)
  useEffect(() => {
    const storedToken = localStorage.getItem('token');
    const storedUser = localStorage.getItem('user');

    if (storedToken && storedUser && storedToken.startsWith(DEMO_TOKEN_PREFIX)) {
      try {
        setUser(JSON.parse(storedUser));
        setToken(storedToken);
        setLoading(false);
        return;
      } catch {}
    }

    if (storedToken && !storedToken.startsWith(DEMO_TOKEN_PREFIX)) {
      // Has real token — try validate async, but don't block
      api.auth.profile()
        .then(res => {
          if (res?.success) {
            setUser(res.user);
            localStorage.setItem('user', JSON.stringify(res.user));
            setToken(storedToken);
          } else {
            localStorage.removeItem('token');
            localStorage.removeItem('user');
          }
        })
        .catch(() => {
          localStorage.removeItem('token');
          localStorage.removeItem('user');
        });
    }

    setLoading(false);
  }, []);

  // Check backend health in background (doesn't affect loading)
  useEffect(() => {
    api.healthCheck().then(() => {}).catch(() => {});
  }, []);

  const login = async (email, password) => {
    try {
      const res = await api.auth.login({ email, password });
      if (res?.success) {
        localStorage.setItem('token', res.token);
        localStorage.setItem('user', JSON.stringify(res.user));
        setToken(res.token);
        setUser(res.user);
        toast.success('Login successful!');
        navigate('/dashboard');
        return res;
      }
    } catch {}

    const users = getDemoUsers();
    const demoUser = users[email];
    if (demoUser && demoUser.password === password) {
      const { password: _, ...safeUser } = demoUser;
      const t = DEMO_TOKEN_PREFIX + Date.now().toString(36);
      localStorage.setItem('token', t);
      localStorage.setItem('user', JSON.stringify(safeUser));
      setToken(t);
      setUser(safeUser);
      toast.success('Logged in');
      navigate('/dashboard');
      return { success: true, user: safeUser, token: t };
    }

    throw new Error('Invalid email or password');
  };

  const register = async (data) => {
    try {
      const res = await api.auth.register(data);
      if (res?.success) {
        toast.success('Account created! Please login.');
        navigate('/login');
        return res;
      }
    } catch {}

    const users = getDemoUsers();
    if (users[data.email]) throw new Error('Email already registered');

    const newUser = {
      id: 'user_' + Date.now().toString(36),
      name: data.name,
      email: data.email,
      password: data.password,
      phone: data.phone || '',
      role: data.role || 'tenant',
    };
    users[data.email] = newUser;
    saveDemoUsers(users);

    const { password: _, ...safeUser } = newUser;
    const t = DEMO_TOKEN_PREFIX + Date.now().toString(36);
    localStorage.setItem('token', t);
    localStorage.setItem('user', JSON.stringify(safeUser));
    setToken(t);
    setUser(safeUser);
    toast.success('Account created! Logged in.');
    navigate('/dashboard');
    return { success: true, user: safeUser, token: t };
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setToken(null);
    setUser(null);
    navigate('/login');
    toast.success('Logged out');
  };

  const hasRole = (...roles) => user ? roles.includes(user.role) : false;

  return (
    <AuthContext.Provider value={{
      user, token, loading,
      login, register, logout, hasRole,
      isAuthenticated: !!token && !!user,
      isAdmin: hasRole('admin', 'landlord'),
      isStaff: hasRole('staff', 'manager'),
      isTenant: hasRole('tenant'),
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

export default AuthContext;
