import axios from 'axios';

const RENDER_API = 'https://rental-management-services-backend-1.onrender.com';
const BASE_URL = import.meta.env.VITE_API_URL || RENDER_API;

class ApiService {
  constructor() {
    this.api = axios.create({
      baseURL: BASE_URL,
      timeout: 8000,
      headers: { 'Content-Type': 'application/json' },
    });

    this.api.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token && !token.startsWith('demo_')) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => Promise.reject(error)
    );

    this.api.interceptors.response.use(
      (response) => response.data,
      (error) => Promise.reject(error)
    );
  }

  healthCheck() {
    return this.api.get('/health', { timeout: 5000 });
  }

  auth = {
    login: (credentials) => this.api.post('/login', credentials, { timeout: 8000 }),
    register: (data) => this.api.post('/register', data, { timeout: 8000 }),
    validate: () => this.api.get('/api/auth/me'),
    profile: () => this.api.get('/profile'),
    forgotPassword: (email) => this.api.post('/auth/forgot-password', { email }),
    resetPassword: (token, password) => this.api.post('/auth/reset-password', { token, password }),
    logout: () => {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      return Promise.resolve();
    }
  };

  properties = {
    getAll: (params) => this.api.get('/api/v1/properties', { params }),
    getById: (id) => this.api.get(`/api/v1/properties/${id}`),
    create: (property) => this.api.post('/api/v1/properties', property),
    update: (id, property) => this.api.put(`/api/v1/properties/${id}`, property),
    delete: (id) => this.api.delete(`/api/v1/properties/${id}`),
    getStats: () => this.api.get('/properties/stats'),
    getPublic: () => this.api.get('/api/properties'),
  };

  dashboard = {
    admin: () => this.api.get('/dashboard/admin'),
    staff: () => this.api.get('/dashboard/staff'),
    user: () => this.api.get('/dashboard/user'),
  };

  maintenance = {
    getAll: (params) => this.api.get('/api/v1/maintenance/requests', { params }),
    getById: (id) => this.api.get(`/api/v1/maintenance/requests/${id}`),
    create: (data) => this.api.post('/api/v1/maintenance/requests', data),
    update: (id, data) => this.api.put(`/api/v1/maintenance/requests/${id}`, data),
    assign: (id, staffId) => this.api.put(`/api/v1/maintenance/requests/${id}/assign`, { staffId }),
    updateStatus: (id, status) => this.api.put(`/api/v1/maintenance/requests/${id}/status`, { status }),
  };

  payments = {
    getAll: (params) => this.api.get('/api/v1/payments', { params }),
    getById: (id) => this.api.get(`/api/v1/payments/${id}`),
    create: (data) => this.api.post('/api/v1/payments', data),
    initiateStripe: (data) => this.api.post('/payments/stripe/create-payment-intent', data),
    initiatePayPal: (data) => this.api.post('/payments/paypal/create-order', data),
    initiateMpesa: (data) => this.api.post('/payments/mpesa/stk-push', data),
    getReceipt: (id) => this.api.get(`/api/v1/payments/${id}/receipt`),
  };

  tenants = {
    getAll: (params) => this.api.get('/api/v1/tenants', { params }),
    getById: (id) => this.api.get(`/api/v1/tenants/${id}`),
    create: (data) => this.api.post('/api/v1/tenants', data),
    update: (id, data) => this.api.put(`/api/v1/tenants/${id}`, data),
    delete: (id) => this.api.delete(`/api/v1/tenants/${id}`),
    getLeases: (tenantId) => this.api.get(`/api/v1/tenants/${tenantId}/leases`),
  };

  reports = {
    income: (params) => this.api.get('/api/v1/reports/income', { params }),
    expenses: (params) => this.api.get('/api/v1/reports/expenses', { params }),
    revenue: (params) => this.api.get('/api/v1/reports/revenue', { params }),
    outstanding: () => this.api.get('/api/v1/reports/outstanding'),
    download: (type, format) => this.api.get(`/api/v1/reports/${type}/download`, {
      params: { format }, responseType: 'blob',
    }),
  };

  notifications = {
    getAll: (params) => this.api.get('/api/v1/notifications', { params }),
    markRead: (id) => this.api.put(`/api/v1/notifications/${id}/read`),
    markAllRead: () => this.api.put('/api/v1/notifications/read-all'),
    send: (data) => this.api.post('/api/v1/notifications/send', data),
    getSettings: () => this.api.get('/api/v1/notifications/settings'),
    updateSettings: (data) => this.api.put('/api/v1/notifications/settings', data),
  };

  documents = {
    getAll: (params) => this.api.get('/api/v1/documents', { params }),
    upload: (formData) => this.api.post('/api/v1/documents/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    }),
    delete: (id) => this.api.delete(`/api/v1/documents/${id}`),
    download: (id) => this.api.get(`/api/v1/documents/${id}/download`, { responseType: 'blob' }),
  };

  system = {
    getInfo: () => this.api.get('/api/v1/info'),
  };
}

export default new ApiService();
