import React, { useState, useEffect } from 'react';
import Modal from '../../components/ui/Modal';
import toast from 'react-hot-toast';
import {
  Users, Plus, Search, Mail, Phone,
  Edit, Trash2, FileText, Download,
} from 'lucide-react';

const TenantsPage = () => {
  const [tenants, setTenants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showModal, setShowModal] = useState(false);
  const [showLeaseModal, setShowLeaseModal] = useState(false);
  const [selectedTenant, setSelectedTenant] = useState(null);
  const [leases, setLeases] = useState([]);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    name: '', email: '', phone: '', propertyName: '', unitNumber: '',
    leaseStart: '', leaseEnd: '', rentAmount: '', status: 'active',
  });

  useEffect(() => { loadTenants(); }, []);

  const loadTenants = () => {
    setTenants([
      { id: '1', name: 'Alice Njeri', email: 'alice.njeri@email.com', phone: '+254 712 345 678', propertyName: 'Sunset Apartments', unitNumber: '3B', leaseStart: '2026-01-01', leaseEnd: '2026-12-31', rentAmount: 1200, status: 'active' },
      { id: '2', name: 'Brian Koech', email: 'brian.koech@email.com', phone: '+254 723 456 789', propertyName: 'Oak Villa', unitNumber: '7A', leaseStart: '2025-06-01', leaseEnd: '2026-06-01', rentAmount: 850, status: 'active' },
      { id: '3', name: 'Carol Wanjiku', email: 'carol.w@email.com', phone: '+254 734 567 890', propertyName: 'Downtown Complex', unitNumber: '12', leaseStart: '2026-03-01', leaseEnd: '2027-03-01', rentAmount: 1500, status: 'active' },
      { id: '4', name: 'Daniel Mwangi', email: 'daniel.m@email.com', phone: '+254 745 678 901', propertyName: 'Pine Court', unitNumber: '2B', leaseStart: '2025-01-01', leaseEnd: '2026-01-01', rentAmount: 950, status: 'expiring' },
      { id: '5', name: 'Emily Kemunto', email: 'emily.k@email.com', phone: '+254 756 789 012', propertyName: 'Hillview Cottages', unitNumber: '5', leaseStart: '2026-02-01', leaseEnd: '2027-02-01', rentAmount: 1100, status: 'active' },
    ]);
    setLoading(false);
  };

  const filtered = tenants.filter(t => {
    const q = search.toLowerCase();
    const matchSearch = t.name?.toLowerCase().includes(q) || t.email?.toLowerCase().includes(q) || t.propertyName?.toLowerCase().includes(q);
    const matchStatus = statusFilter === 'all' || t.status === statusFilter;
    return matchSearch && matchStatus;
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editing) {
      setTenants(prev => prev.map(t => t.id === editing.id ? { ...t, ...form } : t));
      toast.success('Tenant updated');
    } else {
      setTenants(prev => [...prev, { id: Date.now().toString(), ...form }]);
      toast.success('Tenant added');
    }
    setShowModal(false);
    setEditing(null);
    setForm({ name: '', email: '', phone: '', propertyName: '', unitNumber: '', leaseStart: '', leaseEnd: '', rentAmount: '', status: 'active' });
  };

  const handleDelete = (id) => {
    if (!confirm('Delete this tenant? This will also remove their lease data.')) return;
    setTenants(prev => prev.filter(t => t.id !== id));
    toast.success('Tenant removed');
  };

  const viewLeases = (tenant) => {
    setSelectedTenant(tenant);
    setLeases([{
      id: '1', propertyName: tenant.propertyName, unitNumber: tenant.unitNumber,
      startDate: tenant.leaseStart, endDate: tenant.leaseEnd,
      rentAmount: tenant.rentAmount, status: tenant.status, documentUrl: null,
    }]);
    setShowLeaseModal(true);
  };

  const activeCount = tenants.filter(t => t.status === 'active').length;
  const expiringCount = tenants.filter(t => t.status === 'expiring').length;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h2 className="page-heading">Tenants</h2>
          <p className="page-subtitle">{tenants.length} tenants · {activeCount} active · {expiringCount} expiring</p>
        </div>
        <button onClick={() => { setEditing(null); setShowModal(true); }}
          className="btn-primary flex items-center gap-2">
          <Plus className="w-4 h-4" /> Add Tenant
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="stat-card"><p className="stat-label">Total Tenants</p><p className="stat-value">{tenants.length}</p></div>
        <div className="stat-card"><p className="stat-label">Active Leases</p><p className="stat-value text-emerald-600">{activeCount}</p></div>
        <div className="stat-card"><p className="stat-label">Expiring Soon</p><p className="stat-value text-amber-600">{expiringCount}</p></div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search by name, email, or property..." value={search}
            onChange={(e) => setSearch(e.target.value)} className="input-primary pl-9" />
        </div>
        <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="input-primary sm:w-40">
          <option value="all">All Status</option>
          <option value="active">Active</option>
          <option value="expiring">Expiring</option>
          <option value="past">Past</option>
        </select>
      </div>

      {loading ? (
        <div className="text-center py-16"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto" /></div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <Users className="w-12 h-12 mx-auto mb-3 text-gray-300" />
          <p className="text-sm font-medium text-gray-500">No tenants found</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="table-header">Name</th>
                  <th className="table-header">Contact</th>
                  <th className="table-header">Property</th>
                  <th className="table-header">Lease Period</th>
                  <th className="table-header">Rent</th>
                  <th className="table-header">Status</th>
                  <th className="table-header text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filtered.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50">
                    <td className="table-cell">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center shrink-0">
                          <span className="text-sm font-semibold text-blue-600">{t.name?.charAt(0)}</span>
                        </div>
                        <div>
                          <p className="text-sm font-medium text-gray-900">{t.name}</p>
                          <p className="text-xs text-gray-500">Unit {t.unitNumber}</p>
                        </div>
                      </div>
                    </td>
                    <td className="table-cell">
                      <p className="text-sm text-gray-700 flex items-center gap-1"><Mail className="w-3 h-3" /> {t.email}</p>
                      <p className="text-xs text-gray-500 flex items-center gap-1"><Phone className="w-3 h-3" /> {t.phone}</p>
                    </td>
                    <td className="table-cell text-sm text-gray-700">{t.propertyName || '-'}</td>
                    <td className="table-cell text-sm text-gray-500">{t.leaseStart} — {t.leaseEnd}</td>
                    <td className="table-cell text-sm font-semibold">KES {(parseInt(t.rentAmount) * 130).toLocaleString()}</td>
                    <td className="table-cell">
                      <span className={`badge ${t.status === 'active' ? 'badge-green' : 'badge-yellow'}`}>{t.status}</span>
                    </td>
                    <td className="table-cell text-right">
                      <div className="flex items-center justify-end gap-1">
                        <button onClick={() => viewLeases(t)} className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded" title="Lease">
                          <FileText className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => { setEditing(t); setForm({ name: t.name, email: t.email, phone: t.phone || '', propertyName: t.propertyName || '', unitNumber: t.unitNumber || '', leaseStart: t.leaseStart || '', leaseEnd: t.leaseEnd || '', rentAmount: t.rentAmount || '', status: t.status || 'active' }); setShowModal(true); }}
                          className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded" title="Edit">
                          <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => handleDelete(t.id)} className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded" title="Delete">
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <Modal isOpen={showModal} onClose={() => { setShowModal(false); setEditing(null); }} title={editing ? 'Edit Tenant' : 'Add Tenant'} size="lg">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name *</label>
              <input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="input-field" required />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Email *</label>
              <input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} className="input-field" required />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
              <input type="tel" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} className="input-field" placeholder="+254 7XX XXX XXX" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Property</label>
              <input type="text" value={form.propertyName} onChange={(e) => setForm({ ...form, propertyName: e.target.value })} className="input-field" placeholder="Property name" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Unit Number</label>
              <input type="text" value={form.unitNumber} onChange={(e) => setForm({ ...form, unitNumber: e.target.value })} className="input-field" placeholder="e.g. 3B" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Lease Start</label>
              <input type="date" value={form.leaseStart} onChange={(e) => setForm({ ...form, leaseStart: e.target.value })} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Lease End</label>
              <input type="date" value={form.leaseEnd} onChange={(e) => setForm({ ...form, leaseEnd: e.target.value })} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Rent (USD/mo)</label>
              <input type="number" min="0" value={form.rentAmount} onChange={(e) => setForm({ ...form, rentAmount: e.target.value })} className="input-field" />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="input-field">
                <option value="active">Active</option>
                <option value="expiring">Expiring</option>
                <option value="past">Past</option>
              </select>
            </div>
          </div>
          <div className="flex gap-3 pt-2">
            <button type="submit" className="btn-primary flex-1">{editing ? 'Update' : 'Add'} Tenant</button>
            <button type="button" onClick={() => { setShowModal(false); setEditing(null); }} className="btn-secondary flex-1">Cancel</button>
          </div>
        </form>
      </Modal>

      <Modal isOpen={showLeaseModal} onClose={() => setShowLeaseModal(false)}
        title={`Lease — ${selectedTenant?.name || ''}`}>
        {leases.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            <FileText className="w-12 h-12 mx-auto mb-3 text-gray-300" />
            <p>No lease agreements found</p>
          </div>
        ) : (
          <div className="space-y-4">
            {leases.map(lease => (
              <div key={lease.id} className="card p-4">
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between"><span className="text-gray-500">Property</span><span className="font-medium">{lease.propertyName}</span></div>
                  <div className="flex justify-between"><span className="text-gray-500">Unit</span><span className="font-medium">{lease.unitNumber}</span></div>
                  <div className="flex justify-between"><span className="text-gray-500">Period</span><span className="font-medium">{lease.startDate} — {lease.endDate}</span></div>
                  <div className="flex justify-between"><span className="text-gray-500">Rent</span><span className="font-medium text-blue-600">KES {(parseInt(lease.rentAmount) * 130).toLocaleString()}/mo</span></div>
                  <div className="flex justify-between"><span className="text-gray-500">Status</span>
                    <span className={`badge ${lease.status === 'active' ? 'badge-green' : 'badge-yellow'}`}>{lease.status}</span>
                  </div>
                </div>
                {lease.documentUrl && (
                  <a href={lease.documentUrl} target="_blank" rel="noopener noreferrer"
                    className="mt-3 btn-secondary flex items-center gap-2 justify-center text-sm">
                    <Download className="w-4 h-4" /> Download Agreement
                  </a>
                )}
              </div>
            ))}
          </div>
        )}
      </Modal>
    </div>
  );
};

export default TenantsPage;
