import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { Building2, Users, DollarSign, Wrench } from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';

const KPI = ({ label, value, subtitle }) => (
  <div className="bg-white rounded-2xl shadow-sm p-7">
    <p className="text-sm text-gray-500 font-medium">{label}</p>
    <p className="text-4xl font-bold text-gray-900 mt-2 tracking-tight">{value}</p>
    {subtitle && <p className="text-sm text-gray-400 mt-2">{subtitle}</p>}
  </div>
);

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [stats] = useState({
    totalProperties: 24, occupied: 18, vacant: 6,
    totalTenants: 42, monthlyRevenue: 48500, pendingRent: 3200,
    pendingMaintenance: 5,
  });
  const [recentPayments] = useState([
    { id: 1, tenant: 'Alice Njeri', property: 'Sunset Apt 3B', amount: 1200, status: 'paid', date: '15 May 2026' },
    { id: 2, tenant: 'Brian Koech', property: 'Oak Villa 7A', amount: 850, status: 'paid', date: '14 May 2026' },
    { id: 3, tenant: 'Carol Wanjiku', property: 'Downtown 12', amount: 1500, status: 'pending', date: '13 May 2026' },
    { id: 4, tenant: 'Daniel Mwangi', property: 'Pine Court 2B', amount: 950, status: 'paid', date: '12 May 2026' },
    { id: 5, tenant: 'Emily Kemunto', property: 'Hillview 5', amount: 1100, status: 'overdue', date: '10 May 2026' },
  ]);
  const [upcomingRent] = useState([
    { id: 1, tenant: 'Francis Otieno', property: 'Sunset Apt 5A', amount: 1300, dueDate: '01 Jun 2026', status: 'upcoming' },
    { id: 2, tenant: 'Emily Kemunto', property: 'Hillview 5', amount: 1100, dueDate: '28 May 2026', status: 'overdue' },
    { id: 3, tenant: 'Henry Kiprop', property: 'Downtown 8', amount: 2000, dueDate: '25 May 2026', status: 'overdue' },
  ]);
  const [chartData] = useState([
    { month: 'Jan', income: 32000 }, { month: 'Feb', income: 34000 },
    { month: 'Mar', income: 38000 }, { month: 'Apr', income: 42000 },
    { month: 'May', income: 48500 },
  ]);

  const occupancyRate = Math.round((stats.occupied / stats.totalProperties) * 100);
  const collectionRate = Math.round((stats.monthlyRevenue / (stats.monthlyRevenue + stats.pendingRent)) * 100);

  return (
    <div className="space-y-10">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
        <p className="text-sm text-gray-500 mt-1">
          {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPI label="Properties" value={stats.totalProperties} subtitle={`${stats.occupied} occupied · ${stats.vacant} vacant`} />
        <KPI label="Tenants" value={stats.totalTenants} subtitle={`${occupancyRate}% occupancy`} />
        <KPI label="Revenue" value={`KES ${(stats.monthlyRevenue * 130 / 1000).toFixed(0)}K`} subtitle={`${collectionRate}% collected`} />
        <KPI label="Maintenance" value={stats.pendingMaintenance} subtitle="Pending requests" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm p-7">
          <h3 className="text-base font-semibold text-gray-900 mb-6">Revenue</h3>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                <XAxis dataKey="month" tick={{ fontSize: 13, fill: '#9ca3af' }} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ borderRadius: 12, border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', fontSize: 13 }} />
                <Bar dataKey="income" fill="#3b82f6" radius={[8, 8, 0, 0]} maxBarSize={48} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm p-7 space-y-8">
          <div>
            <p className="text-sm text-gray-500 font-medium">Occupancy</p>
            <p className="text-4xl font-bold text-gray-900 mt-2">{occupancyRate}%</p>
            <div className="w-full h-2 bg-gray-100 rounded-full mt-3">
              <div className="h-full bg-emerald-500 rounded-full transition-all" style={{ width: `${occupancyRate}%` }} />
            </div>
            <p className="text-sm text-gray-400 mt-2">{stats.occupied} of {stats.totalProperties} units</p>
          </div>
          <div className="pt-6 border-t border-gray-50">
            <p className="text-sm text-gray-500 font-medium">Collection Rate</p>
            <p className="text-4xl font-bold text-gray-900 mt-2">{collectionRate}%</p>
            <div className="w-full h-2 bg-gray-100 rounded-full mt-3">
              <div className="h-full bg-blue-500 rounded-full transition-all" style={{ width: `${collectionRate}%` }} />
            </div>
            <p className="text-sm text-gray-400 mt-2">KES {(stats.pendingRent * 130).toLocaleString()} outstanding</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-2xl shadow-sm p-7">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-base font-semibold text-gray-900">Recent Payments</h3>
            <button onClick={() => navigate('/payments')} className="text-sm text-blue-600 hover:text-blue-700">View all</button>
          </div>
          <div className="space-y-5">
            {recentPayments.map(p => (
              <div key={p.id} className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-900">{p.tenant}</p>
                  <p className="text-sm text-gray-500">{p.property}</p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-semibold text-gray-900">KES {(p.amount * 130).toLocaleString()}</p>
                  <p className={`text-sm ${p.status === 'paid' ? 'text-emerald-600' : p.status === 'pending' ? 'text-amber-600' : 'text-red-600'}`}>{p.date}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm p-7">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-base font-semibold text-gray-900">Upcoming Rent</h3>
            <button onClick={() => navigate('/payments')} className="text-sm text-blue-600 hover:text-blue-700">Manage</button>
          </div>
          <div className="space-y-5">
            {upcomingRent.map(r => (
              <div key={r.id} className="flex items-center justify-between">
                <div>
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium text-gray-900">{r.tenant}</p>
                    <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${
                      r.status === 'overdue' ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-700'
                    }`}>{r.status}</span>
                  </div>
                  <p className="text-sm text-gray-500">{r.property} · Due {r.dueDate}</p>
                </div>
                <p className="text-sm font-semibold text-gray-900">KES {(r.amount * 130).toLocaleString()}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="flex flex-wrap gap-4">
        <button onClick={() => navigate('/properties?action=add')}
          className="px-5 py-2.5 bg-gray-900 text-white text-sm font-medium rounded-xl hover:bg-gray-800 transition-colors">
          Add Property
        </button>
        <button onClick={() => navigate('/tenants?action=add')}
          className="px-5 py-2.5 bg-white text-gray-900 text-sm font-medium rounded-xl border border-gray-200 hover:bg-gray-50 transition-colors">
          Add Tenant
        </button>
        <button onClick={() => navigate('/payments')}
          className="px-5 py-2.5 bg-white text-gray-900 text-sm font-medium rounded-xl border border-gray-200 hover:bg-gray-50 transition-colors">
          Record Payment
        </button>
        <button onClick={() => navigate('/reports')}
          className="px-5 py-2.5 bg-white text-gray-900 text-sm font-medium rounded-xl border border-gray-200 hover:bg-gray-50 transition-colors">
          View Reports
        </button>
      </div>
    </div>
  );
};

