const DashboardPage = () => {
  const { user } = useAuth();
  const role = user?.role || 'tenant';
  if (role === 'admin' || role === 'landlord') return <AdminDashboard />;
  if (role === 'staff' || role === 'manager') return <StaffDashboard />;
  return <TenantDashboard />;
};

export default DashboardPage;
